    return {"full_name": full_name, "company": None, "address1": "42 Elm St", "address2": None,
            "address3": address3, "city": "Boston", "state": "MA", "postal_code": "02110",
            "country": "US", "phone_number": "617-555-0100", "email_address": "x@marketplace.amazon.com"}

def order(order_id, ship_to):
    return {"id": order_id, "created_date": "2025-01-01T00:00:00Z", "updated_date": "2025-01-02T00:00:00Z",
            "ship_to_address": ship_to, "bill_to_address": IntegrationNotImplemented,
            "line_items": [{"product_id": "p", "sku": "s", "quantity": 1, "warehouse_id": "w"}],
            "shipments": [{"shipment_id": "sh", "ship_from_address": {"address1": "1 Warehouse Way", "city": "Reno"}}],
            "additional_fields": {"marketplace": "US", "programs": [], "li1": {"programs": [], "transparency_codes": []}}}

redacted_address = {**address(REDACTED), "address1": REDACTED, "phone_number": REDACTED, "email_address": REDACTED}
orders = [
    order("fresh", address("Jane Smith")),
    order("with_address3", address("Jane Smith", "Floor 2")),
    order("already_redacted", redacted_address),
    order("cancelled_no_recipient", {**address(None), "address1": None, "phone_number": None, "email_address": None}),
]

def run(module):
    integration = object.__new__(module.Integration)
    with patch.object(module.CartOrder, "get_resources_single_page", return_value=(deepcopy(orders), None)), \
         patch.object(module, "get_resource_implemented", return_value={}):
        start = datetime(2025, 3, 1, tzinfo=timezone.utc)
        return module.Integration.redact_cart_orders(integration, start, start, False, True)

old = run(old_module)
new = run(new_module)
for label, rsp in [("old", old), ("new", new)]:
    print(label, [o["id"] for o in rsp["data"]])
old_by_id = {o["id"]: o for o in old["data"]}
for o in new["data"]:
    if o["id"] in old_by_id and o != old_by_id[o["id"]]:
        for key in o:
            if o[key] != old_by_id[o["id"]][key]:
                print("differs", o["id"], key, old_by_id[o["id"]][key], "->", o[key])
print("shipments ship_from kept:", new["data"][0]["shipments"][0]["ship_from_address"]["address1"])
EOF
uv run python3 $sp/compare_redact.py $sp/amazon_old.py 2>&1 | tail -12

